INSERT INTO `ai_tools` VALUES (7,'query_device','查询设备信息','device','根据设备编码或名称关键词查询设备信息（设备名称、编码、型号、部门、位置、状态等）','GET','/api/device/asset/list',NULL,'{\"type\": \"object\", \"properties\": {\"status\": {\"type\": \"string\", \"title\": \"设备状态\", \"description\": \"按状态筛选\"}, \"keyword\": {\"type\": \"string\", \"title\": \"关键词\", \"description\": \"设备编码或名称关键词\"}, \"department_id\": {\"type\": \"integer\", \"title\": \"部门ID\", \"description\": \"按部门筛选\"}}}',NULL,0,30,1,0,NULL,1,'active',1,'2026-08-08 02:37:41','2026-08-08 02:54:53'),(8,'query_hazard','查询安全隐患','safety','查询安全隐患列表，可按状态筛选（pending待整改/processing整改中/resolved已整改）','GET','builtin://query_hazard',NULL,'{\"type\": \"object\", \"properties\": {\"status\": {\"type\": \"string\", \"title\": \"状态\", \"description\": \"隐患状态，留空查询最近10条\"}}}',NULL,0,30,1,0,NULL,1,'active',2,'2026-08-08 02:37:41','2026-08-08 02:37:41'),(9,'create_repair_order','创建维修工单','device','为故障设备创建维修工单，提交后进入维修流程（高风险写操作，需用户确认）','POST','/api/device/repair/order/add',NULL,'{\"type\": \"object\", \"required\": [\"device_id\", \"fault_description\"], \"properties\": {\"remark\": {\"type\": \"string\", \"title\": \"备注\"}, \"device_id\": {\"type\": \"integer\", \"title\": \"设备ID\", \"description\": \"目标设备ID\"}, \"fault_type\": {\"enum\": [\"mechanical\", \"electrical\", \"hydraulic\", \"pneumatic\", \"software\", \"other\"], \"type\": \"string\", \"title\": \"故障类型\", \"description\": \"故障类型枚举：mechanical(机械)、electrical(电气)、hydraulic(液压)、pneumatic(气动)、software(软件)、other(其他)，必须使用英文枚举值\"}, \"reporter_id\": {\"type\": \"integer\", \"title\": \"报修人ID\", \"description\": \"可选，默认当前用户\"}, \"emergency_level\": {\"enum\": [\"normal\", \"urgent\", \"critical\"], \"type\": \"string\", \"title\": \"紧急程度\", \"default\": \"normal\", \"description\": \"紧急程度：normal(普通)、urgent(紧急)、critical(严重)，默认normal\"}, \"fault_description\": {\"type\": \"string\", \"title\": \"故障描述\", \"description\": \"故障现象描述，必填\"}}}',NULL,1,30,1,0,NULL,1,'active',5,'2026-08-08 02:37:41','2026-08-10 09:29:49'),(10,'query_todo','查询待办事项','common','查询当前用户的待办事项统计','GET','builtin://query_todo',NULL,'{\"type\": \"object\", \"properties\": {}}',NULL,0,30,1,0,NULL,1,'active',4,'2026-08-08 02:37:41','2026-08-08 02:37:41'),(11,'query_attendance','查询考勤记录','hr','查询员工考勤记录，支持按日期范围、打卡结果筛选','GET','/api/hr/attendance/record/list',NULL,'{\"type\": \"object\", \"properties\": {\"page\": {\"type\": \"integer\", \"title\": \"页码\", \"default\": 1}, \"limit\": {\"type\": \"integer\", \"title\": \"每页条数\", \"default\": 20}, \"keyword\": {\"type\": \"string\", \"title\": \"关键词\", \"description\": \"员工姓名关键词\"}, \"end_date\": {\"type\": \"string\", \"title\": \"结束日期\", \"description\": \"格式 YYYY-MM-DD\"}, \"start_date\": {\"type\": \"string\", \"title\": \"开始日期\", \"description\": \"格式 YYYY-MM-DD\"}, \"check_result\": {\"type\": \"string\", \"title\": \"打卡结果\"}, \"department_id\": {\"type\": \"integer\", \"title\": \"部门ID\"}}}',NULL,0,30,1,0,NULL,1,'active',15,'2026-08-08 02:37:41','2026-08-08 02:54:53'),(12,'list_devices','查询设备列表','device','分页查询设备列表，支持按名称/编码关键词、状态、所属部门、设备类型等条件筛选','GET','/api/device/asset/list',NULL,'{\"type\": \"object\", \"properties\": {\"page\": {\"type\": \"integer\", \"title\": \"页码\", \"default\": 1}, \"limit\": {\"type\": \"integer\", \"title\": \"每页条数\", \"default\": 20}, \"status\": {\"type\": \"string\", \"title\": \"设备状态\"}, \"keyword\": {\"type\": \"string\", \"title\": \"关键词\", \"description\": \"设备名称或编码关键词\"}, \"category_id\": {\"type\": \"integer\", \"title\": \"设备分类ID\"}, \"device_type\": {\"type\": \"string\", \"title\": \"设备类型\"}, \"department_id\": {\"type\": \"integer\", \"title\": \"部门ID\"}}}',NULL,0,30,1,0,NULL,1,'active',2,'2026-08-08 02:54:53','2026-08-08 02:54:53'),(13,'query_device_status','查询设备状态','device','查询指定设备的运行状态与状态变更记录（需将 device_id 拼入 URL 路径）','GET','/api/device/asset/status-log/{device_id}',NULL,'{\"type\": \"object\", \"required\": [\"device_id\"], \"properties\": {\"device_id\": {\"type\": \"integer\", \"title\": \"设备ID\", \"description\": \