date_start\": {\"type\": \"string\", \"required\": false, \"description\": \"报价开始日期 YYYY-MM-DD\"}, \"salesperson_id\": {\"type\": \"integer\", \"required\": false, \"description\": \"业务员ID\"}, \"quotation_status\": {\"type\": \"string\", \"required\": false, \"description\": \"报价状态\"}, \"quotation_category\": {\"type\": \"string\", \"required\": false, \"description\": \"报价类别\"}}}',NULL,0,30,1,0,NULL,1,'active',0,'2026-08-16 03:02:56','2026-08-16 03:02:56'),(48,'query_purchase_order','查询采购订单详情','business','根据采购订单ID查询采购订单详细信息，包括采购编号、标题、供应商、下单日期、总金额、订单状态、付款状态、审批状态、收货数量及明细列表等。适用于查看特定采购订单完整资料、采购执行分析等场景。','GET','/api/business/purchase/order/detail/{id}',NULL,'{\"type\": \"object\", \"properties\": {\"id\": {\"type\": \"integer\", \"required\": true, \"description\": \"采购订单ID\"}}}',NULL,0,30,1,0,NULL,1,'active',0,'2026-08-16 03:02:56','2026-08-16 03:02:56'),(49,'list_purchase_orders','查询采购订单列表','business','查询采购订单列表，支持按采购编号、标题、供应商ID、采购申请单号、订单状态、付款状态、审批状态、下单日期范围等多条件筛选，返回分页结果（含状态数量统计）。适用于采购订单盘点、采购进度追踪、供应商绩效分析等场景。','GET','/api/business/purchase/order/list',NULL,'{\"type\": \"object\", \"properties\": {\"page\": {\"type\": \"integer\", \"default\": 1, \"required\": false, \"description\": \"页码\"}, \"title\": {\"type\": \"string\", \"required\": false, \"description\": \"采购标题（模糊）\"}, \"end_date\": {\"type\": \"string\", \"required\": false, \"description\": \"下单结束日期 YYYY-MM-DD\"}, \"order_no\": {\"type\": \"string\", \"required\": false, \"description\": \"采购编号（模糊）\"}, \"pageSize\": {\"type\": \"integer\", \"default\": 10, \"required\": false, \"description\": \"每页条数\"}, \"request_no\": {\"type\": \"string\", \"required\": false, \"description\": \"采购申请单号（模糊）\"}, \"start_date\": {\"type\": \"string\", \"required\": false, \"description\": \"下单开始日期 YYYY-MM-DD\"}, \"supplier_id\": {\"type\": \"integer\", \"required\": false, \"description\": \"供应商ID\"}, \"order_status\": {\"type\": \"integer\", \"required\": false, \"description\": \"订单状态：0草稿 1待审 2已审 3部分收货 4已收货 5已关闭 6已作废\"}, \"payment_status\": {\"type\": \"integer\", \"required\": false, \"description\": \"付款状态：0未付 1部分 2已付\"}, \"approval_status\": {\"type\": \"integer\", \"required\": false, \"description\": \"审批状态：0待提交 1审批中 2通过 3驳回\"}}}',NULL,0,30,1,0,NULL,1,'active',0,'2026-08-16 03:02:56','2026-08-16 03:02:56'),(50,'query_salary','查询员工薪酬明细','hr','按薪酬月份和员工姓名查询工资计算明细，返回基本工资、计件工资、津贴、扣款、应发工资、实发工资等构成。适用于查看员工薪酬详情、薪酬核对等场景。','GET','/api/hr/salary/payroll/list',NULL,'{\"type\": \"object\", \"properties\": {\"page\": {\"type\": \"integer\", \"default\": 1, \"required\": false, \"description\": \"页码\"}, \"month\": {\"type\": \"string\", \"required\": false, \"description\": \"薪酬月份 YYYY-MM（默认当月）\"}, \"pageSize\": {\"type\": \"integer\", \"default\": 10, \"required\": false, \"description\": \"每页条数\"}, \"user_name\": {\"type\": \"string\", \"required\": false, \"description\": \"员工姓名（模糊）\"}}}',NULL,0,30,1,0,NULL,1,'active',0,'2026-08-16 03:02:56','2026-08-16 03:02:56'),(51,'list_salary_slips','查询工资条列表','hr','查询工资条列表，支持按薪酬月份、员工姓名、部门、状态等多条件筛选，返回分页结果（含各状态统计）。适用于薪酬统计、工资条发放管理、薪酬成本分析等场景。','GET','/api/hr/salary/slip/list',NULL,'{\"type\": \"object\", \"properties\": {\"page\": {\"type\": \"integer\", \"default\": 1, \"required\": false, \"description\": \"页码\"}, \"month\": {\"type\": \"string\", \"required\": false, \"description\": \"薪酬月份 YYYY-MM\"}, \"status\": {\"type\": \"integer\", \"required\": false, \"description\": \"状态：1已发放 2已签收 3未签收\"}, \"slip_no\": {\"type\": \"string\", \"required\": false, \"description\": \"工资条编号（模糊）\"}, \"pageSize\": {\"type\": \"integer\", \"default\": 10, \"required\": false, \"description\": \"每页条数\"}, \"user_name\": {\"type\": \"string\", \"required\": false, \"description\": \"员工姓名（模糊）\"}, \"department_id\": {\"type\": \"integer\", \"required\": false, \"description\": \"部门ID\"}}}',NULL,0,30,1,0,NULL,1,'active',0,'2026-08-16 03:02:56','2026-08-16 03:02:56'),(52,'list_recruit_positions','查询招聘职位列表','hr','查询招聘职位列表，支持按职位名称、职位编号、部门、发布状态等多条件筛选，返回分页结果。适用于招聘进度追踪、职位发布管理、招聘统计分析等场景。','GET','/api/hr/recruit/position/list',NULL,'{\"type\": \"object\", \"properties\": {\"page\": {\"type\": \"integer\", \"default\": 1, \"required\": false, \"description\": \"页码\"}, \"pageSize\": {\"type\": \"integer\", \"default\": 10, \"required\": false, \"description\": \"每页条数\"}, \"position_no\": {\"type\": \"string\", \"required\": false, \"description\": \"职位编号（模糊）\"}, \"department_id\": {\"type\": \"integer\", \"required\": false, \"description\": \"部门ID\"}, \"position_name\": {\"type\": \"string\", \"required\": false, \"description\": \"职位名称（模糊）\"}, \"publish_status\": {\"type\": \"integer\", \"required\": false, \"description\": \"发布状态：0草稿 1发布中 2已截止 3已关闭\"}}}',NULL,0,30,1,0,NULL,1,'active',0,'2026-08-16 03:02:56','2026-08-16 03:02:56'),(53,'search_knowledge','搜索知识库文档','ai','在企业AI知识库中按关键词检索文档切片，返回匹配的文档片段（含相似度评分）。注意：kb_id 必填（知识库标识，可通过知识库列表获取）；当前为关键词检索，向量检索待接入后升级。适用于查找设备维修手册、安全操作规程、培训课件、事故案例等企业知识文档。','POST','/api/ai/knowledge/retrieve',NULL,'{\"type\": \"object\", \"properties\": {\"kb_id\": {\"type\": \"string\", \"required\": true, \"description\": \"知识库ID（必填）\"}, \"query\": {\"type\": \"string\", \"required\": true, \"description\": \"检索关键词或问题（必填）\"}, \"top_k\": {\"type\": \"integer\", \"default\": 5, \"required\": false, \"description\": \"返回结果条数（1-20）\"}}}',NULL,0,30,1,0,NULL,1,'active',0,'2026-08-16 03:02:56','2026-08-16 03:02:56');
