INSERT INTO `business_contract_templates` VALUES (1,'TPL-20260101-0001','采购合同','standard','purchase','<!DOCTYPE html>\n<html>\n<head>\n<meta charset=\"UTF-8\">\n<style>\nbody { font-family: SimSun, serif; font-size: 14px; padding: 40px; }\n.contract-title { text-align: center; font-size: 22px; font-weight: bold; padding: 20px 0; }\n.contract-info { margin: 10px 0; }\ntable { width: 100%; border-collapse: collapse; margin: 15px 0; }\nth, td { border: 1px solid #000; padding: 6px 10px; text-align: center; }\nth { background: #f5f5f5; font-weight: bold; }\n.text-left { text-align: left; }\n.text-right { text-align: right; }\n.sign-area { margin-top: 30px; }\n.sign-area table { border: 1px solid #000; border-collapse: collapse; }\n.sign-area td { border: none; vertical-align: top; padding: 10px 20px; text-align: left; }\n.clause { margin: 8px 0; }\n.sign-area td:first-child { border-right: 1px solid #000; }\n.contract-info-table { width: 100%; border: none; margin: 10px 0; }\n.contract-info-table td { border: none; padding: 2px 0; }\n.contract-info-table td.left { width: 60%; text-align: left; }\n.contract-info-table td.right { text-align: left; }\n</style>\n</head>\n<body><div style=\"text-align:left;font-size:13px;color:#333;margin-bottom:10px;\">合同编号：{contract_no}</div>\n\n<div class=\"contract-title\">购 销 合 同</div>\n\n<div class=\"contract-info\">\n  <table class=\"contract-info-table\">\n    <tr><td class=\"left\"><strong>甲方：</strong>{customer_name}</td><td class=\"right\"><strong>签订时间：</strong>{sign_date}</td></tr>\n    <tr><td class=\"left\"><strong>乙方：</strong>{supplier_name}</td><td class=\"right\"><strong>签订地点：</strong>{sign_location}</td></tr>\n  </table>\n</div>\n\n<p><strong>第一条　序号、名称、型号、数量、价款等。</strong></p>\n\n{items_table}\n\n<p><strong>第二条　付款方式：</strong>{payment_terms}</p>\n\n<p><strong>第三条　质量标准：</strong>确保设备或设施满足甲方的使用需求。</p>\n\n<p><strong>第四条　交货方式及运输费用：</strong>由乙方负责。</p>\n\n<p><strong>第五条　验收期限：</strong>收到货后7日内验收，逾期不验收视为合格。</p>\n\n<p><strong>第六条　合同争议解决方式：</strong>本合同履行过程中发生的争议，由双方协商解决，协商不成的，提交需方当地人民法院起诉处理。</p>\n\n<p><strong>第七条　违约责任：</strong>按《民法典》规定，违约方承担相应违约责任。</p>\n\n<p><strong>第八条　本合同一式四份，甲乙双方各持两份。</strong></p>\n\n<p><strong>第九条　本合同经双方法定代表人或委托代理人签字盖章后生效。</strong></p>\n\n<div class=\"sign-area\">\n  <table>\n    <tr>\n      <td style=\"width:50%;\">\n        <p><strong>甲方</strong></p>\n        <p>甲方（章）：{customer_seal}</p>\n        <p>地址：{customer_address}</p>\n        <p>法定代表人：{customer_legal_person}</p>\n        <p>委托代理人：{customer_agent}</p>\n        <p>电话：{customer_phone}</p>\n        <p>传真：{customer_fax}</p>\n        <p>开户银行：{customer_bank}</p>\n        <p>帐号：{customer_account}</p>\n        <p>税号：{customer_tax}</p>\n      </td>\n      <td style=\"width:50%;\">\n        <p><strong>乙方</strong></p>\n        <p>乙方（章）：{supplier_seal}</p>\n        <p>地址：{supplier_address}</p>\n        <p>法定代表人：{supplier_legal_person}</p>\n        <p>委托代理人：{supplier_agent}</p>\n        <p>电话：{supplier_phone}</p>\n        <p>传真：{supplier_fax}</p>\n        <p>开户银行：{supplier_bank}</p>\n        <p>帐号：{supplier_account}</p>\n        <p>税号：{supplier_tax}</p>\n      </td>\n    </tr>\n  </table>\n</div>\n\n</body>\n</html>',NULL,'[\"contract_no\", \"contract_name\", \"sign_date\", \"sign_location\", \"customer_name\", \"supplier_name\", \"items_table\", \"total_amount\", \"total_amount_cn\", \"payment_terms\"]',1,1,2,0,'system','2026-08-11 16:14:50','2026-08-11 17:43:18',NULL),(2,'TPL-20260811-0001','购销合同','standard','sales','<!DOCTYPE html>\n<html>\n<head>\n<meta charset=\"UTF-8\">\n<style>\nbody { font-family: SimSun, serif; font-size: 14px; padding: 40px; }\n.contract-title { text-align: center; font-size: 22px; font-weight: bold; padding: 20px 0; }\n.contract-info { margin: 10px 0; }\ntable { width: 100%; border-collapse: collapse; margin: 15px 0; }\nth, td { border: 1px solid #000; padding: 6px 10px; text-align: center; }\nth { background: #f5f5f5; font-weight: bold; }\n.text-left { text-align: left; }\n.text-right { text-align: right; }\n.sign-area { margin-top: 30px; }\n.sign-area table { border: 1px solid #000; border-collapse: collapse; }\n.sign-area td { border: none; vertical-align: top; padding: 10px 20px; text-align: left; }\n.clause { margin: 8px 0; }\n.sign-area td:first-child { border-right: 1px solid #000; }\n.contract-info-table { width: 100%; border: none; margin: 10px 0; }\n.contract-info-table td { border: none; padding: 2px 0; }\n.contract-info-table td.left { width: 60%; text-align: left; }\n.contract-info-table td.right { text-align: left; }\n</style>\n</head>\n<body>\n\n<div class=\"contract-title\">购 销 合 同</div>\n\n<div class=\"contract-info\">\n  <table class=\"contract-info-table\">\n    <tr><td class=\"left\"><strong>甲方：</strong>{customer_name}</td><td class=\"right\"><strong>签订时间：</strong>{sign_date}</td></tr>\n    <tr><td class=\"left\"><strong>乙方：</strong>{supplier_name}</td><td class=\"right\"><strong>签订地点：</strong>{sign_location}</td></tr>\n  </table>\n</div>\n\n<p><strong>第一条　序号、名称、型号、数量、价款等。</strong></p>\n\n{items_table}\n\n<p><strong>第二条　付款方式：</strong>{payment_terms}</p>\n\n<p><strong>第三条　质量标准：</strong>确保设备或设施满足甲方的使用需求。</p>\n\n<p><strong>第四条　交货方式及运输费用：</strong>由乙方负责。</p>\n\n<p><strong>第五条　验收期限：</strong>收到货后7日内验收，逾期不验收视为合格。</p>\n\n<p><strong>第六条　合同争议解决方式：</strong>本合同履行过程中发生的争议，由双方协商解决，协商不成的，提交需方当地人民法院起诉处理。</p>\n\n<p><strong>第七条　违约责任：</strong>按《民法典》规定，违约方承担相应违约责任。</p>\n\n<p><strong>第八条　本合同一式四份，甲乙双方各持两份。</strong></p>\n\n<p><strong>第九条　本合同经双方法定代表人或委托代理人签字盖章后生效。</strong></p>\n\n<div class=\"sign-area\">\n  <table>\n    <tr>\n      <td style=\"width:50%;\">\n        <p><strong>甲方</strong></p>\n        <p>甲方（章）：{customer_seal}</p>\n        <p>地址：{customer_address}</p>\n        <p>法定代表人：{customer_legal_person}</p>\n        <p>委托代理人：{customer_agent}</p>\n        <p>电话：{customer_phone}</p>\n        <p>传真：{customer_fax}</p>\n        <p>开户银行：{customer_bank}</p>\n        <p>帐号：{customer_account}</p>\n        <p>税号：{customer_tax}</p>\n      </td>\n      <td style=\"width:50%;\"