INSERT INTO `business_contracts` VALUES (8,'CT-20260811-0003','综采液压支架配件采购合同','purchase',1,NULL,1,NULL,'华能装备制造有限公司','李经理','0352-7654321',120000.00,'预付款30%，发货前付40%，验收合格付25%，质保金5%','[{\"qty\": \"2\", \"name\": \"液压支架\", \"unit\": \"台\", \"model\": \"ZY4000\", \"price\": \"50000\", \"amount\": \"100000\"}, {\"qty\": \"4\", \"name\": \"立柱\", \"unit\": \"根\", \"model\": \"LG200\", \"price\": \"5000\", \"amount\": \"20000\"}]','2026-08-11','山西省忻州市宁武县','2026-08-12','2026-12-31','completed','pending',NULL,NULL,NULL,NULL,NULL,'\n\n\n\n\nbody { font-family: SimSun, serif; font-size: 14px; padding: 40px; }\n.contract-title { text-align: center; font-size: 22px; font-weight: bold; padding: 20px 0; }\n.contract-info { margin: 10px 0; ','<!DOCTYPE html>\n<html>\n<head>\n<meta charset=\"UTF-8\">\n<style>\nbody { font-family: SimSun, serif; font-size: 14px; padding: 40px; }\n.contract-title { text-align: center; font-size: 22px; font-weight: bold; padding: 20px 0; }\n.contract-info { margin: 10px 0; }\ntable { width: 100%; border-collapse: collapse; margin: 15px 0; }\nth, td { border: 1px solid #000; padding: 6px 10px; text-align: center; }\nth { background: #f5f5f5; font-weight: bold; }\n.text-left { text-align: left; }\n.text-right { text-align: right; }\n.sign-area { margin-top: 30px; }\n.sign-area table { border: 1px solid #000; border-collapse: collapse; }\n.sign-area td { border: none; vertical-align: top; padding: 10px 20px; text-align: left; }\n.clause { margin: 8px 0; }\n.sign-area td:first-child { border-right: 1px solid #000; }\n.contract-info-table { width: 100%; border: none; margin: 10px 0; }\n.contract-info-table td { border: none; padding: 2px 0; }\n.contract-info-table td.left { width: 60%; text-align: left; }\n.contract-info-table td.right { text-align: left; }\n</style>\n</head>\n<body>\n\n<div class=\"contract-title\">购 销 合 同</div>\n\n<div class=\"contract-info\">\n  <table class=\"contract-info-table\">\n    <tr><td class=\"left\"><strong>甲方：</strong>山西大运华能装备制造有限公司</td><td class=\"right\"><strong>签订时间：</strong>2026年08月11日</td></tr>\n    <tr><td class=\"left\"><strong>乙方：</strong>华能装备制造有限公司</td><td class=\"right\"><strong>签订地点：</strong>山西省忻州市宁武县</td></tr>\n  </table>\n</div>\n\n<p><strong>第一条　序号、名称、型号、数量、价款等。</strong></p>\n\n<table><tr><th>序号</th><th>名称</th><th>型号</th><th>单位</th><th>数量</th><th>单价（元）</th><th>金额（元）</th><th>备注</th></tr><tr><td>1</td><td>液压支架</td><td>ZY4000</td><td>台</td><td>2</td><td class=\"text-right\">50,000.00</td><td class=\"text-right\">100,000.00</td><td></td></tr><tr><td>2</td><td>立柱</td><td>LG200</td><td>根</td><td>4</td><td class=\"text-right\">5,000.00</td><td class=\"text-right\">20,000.00</td><td></td></tr><tr><td colspan=\"8\" class=\"text-right\"><strong>含税总金额：120,000.00元　　人民币大写：壹拾贰万元整</strong></td></tr><tr><td colspan=\"8\" class=\"text-right\">不含税金额：106,194.69元　　税额：13,805.31元</td></tr></table>\n\n<p><strong>第二条　付款方式：</strong>预付款30%，发货前付40%，验收合格付25%，质保金5%</p>\n\n<p><strong>第三条　质量标准：</strong>确保设备或设施满足甲方的使用需求。</p>\n\n<p><strong>第四条　交货方式及运输费用：</strong>由乙方负责。</p>\n\n<p><strong>第五条　验收期限：</strong>收到货后7日内验收，逾期不验收视为合格。</p>\n\n<p><strong>第六条　合同争议解决方式：</strong>本合同履行过程中发生的争议，由双方协商解决，协商不成的，提交需方当地人民法院起诉处理。</p>\n\n<p><strong>第七条　违约责任：</strong>按《民法典》规定，违约方承担相应违约责任。</p>\n\n<p><strong>第八条　本合同一式四份，甲乙双方各持两份。</strong></p>\n\n<p><strong>第九条　本合同经双方法定代表人或委托代理人签字盖章后生效。</strong></p>\n\n<div class=\"sign-area\">\n  <table>\n    <tr>\n      <td style=\"width:50%;\">\n        <p><strong>甲方</strong></p>\n        <p>甲方（章）：</p>\n        <p>地址：山西省忻州市宁武县阳方口镇大水口（工业园区）</p>\n        <p>法定代表人：李军</p>\n        <p>委托代理人：李建军</p>\n        <p>电话：18535078148</p>\n        <p>传真：0350-XXXXXXX</p>\n        <p>开户银行：中国工商银行忻州分行宁武支行</p>\n        <p>帐号：1234567890123456789</p>\n        <p>税号：91140925MA0LHFD45L</p>\n      </td>\n      <td style=\"width:50%;\">\n        <p><strong>乙方</strong></p>\n        <p>乙方（章）：</p>\n        <p>地址：山西省大同市开发区</p>\n        <p>法定代表人：</p>\n        <p>委托代理人：</p>\n        <p>电话：0352-7654321</p>\n        <p>传真：</p>\n        <p>开户银行：建设银行大同分行</p>\n        <p>帐号：1500000000000000000</p>\n        <p>税号：91140000000000000Y</p>\n      </td>\n    </tr>\n  </table>\n</div>\n\n</body>\n</html>\n<!--TPL:1-->',40,'[]',NULL,NULL,NULL,NULL,1,0,0,'system','2026-08-11 17:53:27','2026-08-12 14:30:45',NULL);
