INSERT INTO `safety_exam_answer` VALUES (5,2,3,'管理员',0,NULL,NULL,0,0,1,NULL,0,0,0,0,NULL,NULL,NULL,1,NULL,'2026-08-21 09:08:00','2026-08-21 09:08:00'),(6,2,73,'李垚',0,NULL,NULL,0,0,1,NULL,0,0,0,0,NULL,NULL,NULL,1,NULL,'2026-08-21 09:08:00','2026-08-21 09:08:00'),(7,2,81,'郭建',0,NULL,NULL,0,0,1,NULL,0,0,0,0,NULL,NULL,NULL,1,NULL,'2026-08-21 09:08:00','2026-08-21 09:08:00'),(8,2,82,'李兴军',0,NULL,NULL,0,0,1,NULL,0,0,0,0,NULL,NULL,NULL,1,NULL,'2026-08-21 09:08:00','2026-08-21 09:08:00'),(9,3,3,'管理员',0,NULL,NULL,0,0,1,NULL,0,0,0,0,NULL,NULL,NULL,1,NULL,'2026-08-21 09:09:20','2026-08-21 09:09:20'),(10,3,73,'李垚',2,NULL,'[{\"answer\": \"C\", \"analysis\": \"车间主任是车间安全生产的第一责任人，对车间安全生产工作全面负责。\", \"selected\": \"B\", \"is_correct\": false, \"question_id\": 1, \"question_text\": \"车间安全生产的第一责任人是？\", \"question_type\": \"single\"}, {\"answer\": \"B\", \"analysis\": \"《安全生产法》规定，安全生产工作应当以人为本，坚持安全第一、预防为主、综合治理的方针。\", \"selected\": \"A\", \"is_correct\": false, \"question_id\": 2, \"question_text\": \"我国安全生产的方针是？\", \"question_type\": \"single\"}, {\"answer\": \"A\", \"analysis\": \"特种作业人员必须按照国家有关规定经专门的安全作业培训，取得特种作业操作资格证书，方可上岗作业。\", \"selected\": \"B\", \"is_correct\": false, \"question_id\": 3, \"question_text\": \"特种作业人员必须取得什么证书方可上岗？\", \"question_type\": \"single\"}, {\"answer\": \"A\", \"analysis\": \"发现火灾隐患应当立即报告，并采取相应的防范措施，避免火灾事故发生。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 4, \"question_text\": \"发现火灾隐患应当如何处理？\", \"question_type\": \"single\"}, {\"answer\": \"D\", \"analysis\": \"灭火器应对准火焰根部喷射，才能有效扑灭火源。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 5, \"question_text\": \"使用灭火器扑救火灾时，应对准火焰的哪个部位喷射？\", \"question_type\": \"single\"}, {\"answer\": \"D\", \"analysis\": \"车间安全通道宽度一般不小于1.5米，确保人员疏散和车辆通行安全。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 6, \"question_text\": \"车间内安全通道的宽度一般不应小于？\", \"question_type\": \"single\"}, {\"answer\": \"B\", \"analysis\": \"戴安全帽是正确安全行为，其余三项均为违章操作行为。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 7, \"question_text\": \"下列哪种行为不属于违章操作？\", \"question_type\": \"single\"}, {\"answer\": \"C\", \"analysis\": \"设备检修时必须在电源开关处悬挂“禁止合闸”标识，防止他人误操作。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 8, \"question_text\": \"设备检修时，应在电源开关处悬挂什么标识？\", \"question_type\": \"single\"}, {\"answer\": \"A\", \"analysis\": \"叉车在厂区道路行驶速度一般不超过10km/h，在车间内不超过5km/h。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 9, \"question_text\": \"叉车在厂区道路行驶时，速度一般不得超过？\", \"question_type\": \"single\"}, {\"answer\": \"C\", \"analysis\": \"锅炉水位表每班至少冲洗一次，确保水位显示清晰准确。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 10, \"question_text\": \"锅炉运行中，水位表应每班冲洗几次？\", \"question_type\": \"single\"}, {\"answer\": \"A\", \"analysis\": \"车间噪音超过85分贝时，操作人员应佩戴防护耳塞，保护听力。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 11, \"question_text\": \"车间内噪音超过多少分贝时应佩戴防护耳塞？\", \"question_type\": \"single\"}, {\"answer\": \"D\", \"analysis\": \"化学品泄漏时应首先切断泄漏源，防止泄漏扩大，然后再进行清理和报告。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 12, \"question_text\": \"化学品泄漏时应首先采取什么措施？\", \"question_type\": \"single\"}, {\"answer\": \"A\", \"analysis\": \"叉车装卸货物时货叉离地高度应保持在200-300mm，确保行驶稳定。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 13, \"question_text\": \"叉车装卸货物时，货叉离地高度应保持在？\", \"question_type\": \"single\"}, {\"answer\": \"C\", \"analysis\": \"干粉灭火器适用于扑救电器火灾，水型灭火器不能用于电器火灾。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 14, \"question_text\": \"以下哪种灭火器适用于扑救电器火灾？\", \"question_type\": \"single\"}, {\"answer\": \"B\", \"analysis\": \"车间内行灯、手持电动工具等应采用36V及以下安全电压。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 15, \"question_text\": \"车间安全电压为？\", \"question_type\": \"single\"}, {\"answer\": \"A\", \"analysis\": \"特种设备使用单位应当在设备投入使用前或者投入使用后30日内办理使用登记。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 16, \"question_text\": \"特种设备使用单位应在设备投入使用前多少日内办理使用登记？\", \"question_type\": \"single\"}, {\"answer\": \"B\", \"analysis\": \"起重机吊运重物时吊钩应垂直起吊，斜吊角度不得超过5°，防止钢丝绳脱槽。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 17, \"question_text\": \"起重机吊运重物时，吊钩应垂直起吊，斜吊角度不得超过？\", \"question_type\": \"single\"}, {\"answer\": \"D\", \"analysis\": \"消防栓周围1.5米内不得堆放物品，确保消防栓能够快速取用。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 18, \"question_text\": \"车间内消防栓周围多少米内不得堆放物品？\", \"question_type\": \"single\"}, {\"answer\": \"A\", \"analysis\": \"电梯维护保养应至少每15日进行一次，确保电梯安全运行。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 19, \"question_text\": \"电梯维护保养应至少每多少日进行一次？\", \"question_type\": \"single\"}, {\"answer\": \"C\", \"analysis\": \"安全标志颜色中红色表示禁止，黄色表示警告，绿色表示指示，蓝色表示指令。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 20, \"question_text\": \"以下哪项不是车间常见的安全标志颜色？\", \"question_type\": \"single\"}, {\"answer\": \"C\", \"analysis\": \"压力容器安全阀每年至少校验一次，确保安全阀灵敏可靠。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 21, \"question_text\": \"压力容器的安全阀应每年校验几次？\", \"question_type\": \"single\"}, {\"answer\": \"D\", \"analysis\": \"配电箱门应保持关闭状态，防止无关人员接触带电设备。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 22, \"question_text\": \"车间配电箱的门应保持什么状态？\", \"question_type\": \"single\"}, {\"answer\": \"C\", \"analysis\": \"叉车驾驶员必须持有叉车操作证，方可上岗操作叉车。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 23, \"question_text\": \"叉车驾驶员必须持有哪类驾驶证？\", \"question_type\": \"single\"}, {\"answer\": \"C\", \"analysis\": \"设备正常停机不属于事故，其他三项均属于特种设备事故。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 24, \"question_text\": \"以下哪种情况不属于特种设备事故？\", \"question_type\": \"single\"}, {\"answer\": \"D\", \"analysis\": \"车间安全出口应保持畅通，不得锁闭或堆放物品，确保紧急疏散。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 25, \"question_text\": \"车间安全出口应保持什么状态？\", \"question_type\": \"single\"}, {\"answer\": \"A\", \"analysis\": \"压力容器操作人员每3年进行一次资格复审，确保操作技能和知识更新。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 26, \"question_text\": \"压力容器操作人员应每几年进行一次复审？\", \"question_type\": \"single\"}, {\"answer\": \"D\", \"analysis\": \"起重机械严禁斜吊、歪拉，重物倾斜时起吊会造成钢丝绳脱槽或吊物坠落。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 27, \"question_text\": \"车间行车操作时，严禁在什么情况下起吊重物？\", \"question_type\": \"single\"}, {\"answer\": \"D\", \"analysis\": \"厂区道路转弯半径一般不小于8米，确保车辆安全转弯。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 28, \"question_text\": \"机动车在厂区道路的转弯半径一般不应小于？\", \"question_type\": \"single\"}, {\"answer\": \"A\", \"analysis\": \"火警报警电话为119，发现火灾应立即拨打119报警。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 29, \"question_text\": \"车间消防报警电话为？\", \"question_type\": \"single\"}, {\"answer\": \"D\", \"analysis\": \"电梯紧急停止按钮为红色，紧急情况下按下可停止电梯运行。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 30, \"question_text\": \"电梯紧急停止按钮的颜色为？\", \"question_type\": \"single\"}, {\"answer\": \"B\", \"analysis\": \"台式钻床不属于特种设备，属于普通机械设备。锅炉、压力容器、叉车均属于特种设备。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 31, \"question_text\": \"以下哪种不属于特种设备？\", \"question_type\": \"single\"}, {\"answer\": \"A\", \"analysis\": \"车间设备之间安全距离不小于0.8米，确保操作人员通行安全和设备维护空间。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 32, \"question_text\": \"车间设备布局中，设备之间安全距离不应小于？\", \"question_type\": \"single\"}, {\"answer\": \"D\", \"analysis\": \"叉车载货下坡时应倒车下坡，确保驾驶员视线良好，防止货物遮挡视线。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 33, \"question_text\": \"叉车载货下坡时应如何操作？\", \"question_type\": \"single\"}, {\"answer\": \"C\", \"analysis\": \"锅炉安全阀每年至少校验一次，确保安全阀性能可靠。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 34, \"question_text\": \"锅炉安全阀的校验周期为？\", \"question_type\": \"single\"}, {\"answer\": \"C\", \"analysis\": \"文明生产是车间基本要求，其他三项均为不良行为。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 35, \"question_text\": \"以下哪种行为在车间内是允许的？\", \"question_type\": \"single\"}, {\"answer\": \"D\", \"analysis\": \"起重机操作时吊物下方严禁人员通过或停留，防止吊物坠落造成伤害。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 36, \"question_text\": \"起重机操作时，吊物下方严禁？\", \"question_type\": \"single\"}, {\"answer\": \"B\", \"analysis\": \"车间用电设备每年至少进行一次绝缘检测，确保设备绝缘性能良好。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 37, \"question_text\": \"车间用电设备应每几年进行一次绝缘检测？\", \"question_type\": \"single\"}, {\"answer\": \"C\", \"analysis\": \"叉车作业时货物高度不应超过操作人员视线，确保驾驶员视野良好。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 38, \"question_text\": \"叉车作业时，货叉上的货物高度不应超过？\", \"question_type\": \"single\"}, {\"answer\": \"A\", \"analysis\": \"压力容器运行中严禁超过设计压力，防止容器超压爆炸。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 39, \"question_text\": \"压力容器运行中严禁超过什么参数？\", \"question_type\": \"single\"}, {\"answer\": \"A\", \"analysis\": \"急救药箱药品过期应及时更换，确保急救药品有效可用。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 40, \"question_text\": \"车间配备的急救药箱应定期检查，药品过期应如何处理？\", \"question_type\": \"single\"}, {\"answer\": \"B\", \"analysis\": \"电梯应在显著位置张贴安全使用说明和应急救援电话，方便乘客使用和求助。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 41, \"question_text\": \"电梯使用单位应在电梯显著位置张贴？\", \"question_type\": \"single\"}, {\"answer\": \"A\", \"analysis\": \"车间一般照明照度不应低于200lx，确保操作人员视觉清晰。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 42, \"question_text\": \"车间照明照度一般不应低于？\", \"question_type\": \"single\"}, {\"answer\": \"A\", \"analysis\": \"叉车在车间内行驶速度不得超过5km/h，确保车间内行驶安全。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 43, \"question_text\": \"叉车在车间内行驶速度不得超过？\", \"question_type\": \"single\"}, {\"answer\": \"A\", \"analysis\": \"锅炉缺水运行会导致炉管过热变形甚至锅炉爆炸，是锅炉运行中的重大隐患。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 44, \"question_text\": \"锅炉运行中严禁缺水运行，缺水会造成什么后果？\", \"question_type\": \"single\"}, {\"answer\": \"B\", \"analysis\": \"遵守操作规程是车间安全生产的基本要求。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 45, \"question_text\": \"以下哪项是车间安全生产的基本要求？\", \"question_type\": \"single\"}, {\"answer\": \"B\", \"analysis\": \"起重机吊钩每年至少进行一次全面检查，发现裂纹、变形应立即更换。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 46, \"question_text\": \"起重机的吊钩每年应进行多少次检查？\", \"question_type\": \"single\"}, {\"answer\": \"B\", \"analysis\": \"焊接作业应戴防护眼镜和面罩，防止弧光伤害眼睛和面部。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 47, \"question_text\": \"车间内焊接作业应采取什么防护措施？\", \"question_type\": \"single\"}, {\"answer\": \"D\", \"analysis\": \"压力容器安全附件包括安全阀、压力表、液位计，温度计不属于安全附件。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 48, \"question_text\": \"压力容器安全附件不包括？\", \"question_type\": \"single\"}, {\"answer\": \"B\", \"analysis\": \"叉车停车后货叉应平放落地，防止货叉升起造成安全隐患。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 49, \"question_text\": \"叉车停车后，货叉应如何放置？\", \"question_type\": \"single\"}, {\"answer\": \"A\", \"analysis\": \"车间安全生产的核心是预防为主，通过预防措施避免事故发生。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 50, \"question_text\": \"车间安全生产的核心是？\", \"question_type\": \"single\"}, {\"answer\": \"A,B,C,D,E\", \"analysis\": \"车间常见的危险源包括机械伤害、触电、火灾、高处坠落、噪声等多种因素。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 51, \"question_text\": \"以下哪些属于车间常见的危险源？\", \"question_type\": \"multiple\"}, {\"answer\": \"A,B,C,D,E\", \"analysis\": \"锅炉、压力容器、叉车、电梯、起重机均属于特种设备，需定期检验。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 52, \"question_text\": \"以下哪些属于特种设备？\", \"question_type\": \"multiple\"}, {\"answer\": \"B,C,D,E\", \"analysis\": \"叉车安全操作包括持证上岗、定期检查、严禁超载、货叉升起后不得维修。叉车严禁载人行驶。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 53, \"question_text\": \"叉车安全操作包括哪些？\", \"question_type\": \"multiple\"}, {\"answer\": \"A,B,C,D,E\", \"analysis\": \"车间火灾常见原因包括电气线路老化、违规动火作业、可燃物堆积、设备过热、人为纵火等。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 54, \"question_text\": \"车间火灾的常见原因包括？\", \"question_type\": \"multiple\"}, {\"answer\": \"A,B,C,D\", \"analysis\": \"特种设备安全附件包括安全阀、压力表、液位计、爆破片等，温度计不属于安全附件。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 55, \"question_text\": \"以下哪些是特种设备安全附件？\", \"question_type\": \"multiple\"}, {\"answer\": \"A,B,C,D\", \"analysis\": \"车间用电安全措施包括接地保护、漏电保护、过载保护、短路保护。随意接线是违章行为。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 56, \"question_text\": \"车间用电安全措施包括？\", \"question_type\": \"multiple\"}, {\"answer\": \"B,C,D,E\", \"analysis\": \"特种设备使用单位应办理使用登记、定期检验、制定应急预案、配备操作人员。随意改装设备是违法行为。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 57, \"question_text\": \"特种设备使用单位应当履行哪些义务？\", \"question_type\": \"multiple\"}, {\"answer\": \"A,B,C,D\", \"analysis\": \"车间安全通道应畅通无阻、标识清晰、宽度达标、照明充足，不得堆放物料。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 58, \"question_text\": \"车间安全通道应满足哪些要求？\", \"question_type\": \"multiple\"}, {\"answer\": \"A,B,C,E\", \"analysis\": \"戴手套操作旋转设备、穿高跟鞋进入车间、酒后上岗、设备运行时检修均属于违章操作。佩戴安全帽是正确行为。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 59, \"question_text\": \"以下哪些行为属于车间违章操作？\", \"question_type\": \"multiple\"}, {\"answer\": \"A,B,C,E\", \"analysis\": \"锅炉运行中应监视水位、压力、温度、流量等关键参数，确保锅炉安全运行。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 60, \"question_text\": \"锅炉运行中应监视哪些参数？\", \"question_type\": \"multiple\"}, {\"answer\": \"A,B,C,D,E\", \"analysis\": \"叉车日常检查包括轮胎气压、制动系统、灯光系统、货叉变形、发动机机油等项目。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 61, \"question_text\": \"叉车的日常检查项目包括？\", \"question_type\": \"multiple\"}, {\"answer\": \"A,B,C,D\", \"analysis\": \"车间灭火器应类型匹配、数量充足、位置合理、定期检查。灭火器不得随意挪动。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 62, \"question_text\": \"车间灭火器的配置要求包括？\", \"question_type\": \"multiple\"}, {\"answer\": \"A,B,C,D\", \"analysis\": \"电梯安全使用注意事项包括不超载、不扒门、不在轿厢内跳跃、紧急情况按警铃。电梯故障时严禁强行开门。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 63, \"question_text\": \"电梯安全使用注意事项包括？\", \"question_type\": \"multiple\"}, {\"answer\": \"A,B,C,D,E\", \"analysis\": \"车间个人防护用品包括安全帽、防护眼镜、防护手套、防噪耳塞、防尘口罩等。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 64, \"question_text\": \"以下哪些属于车间个人防护用品？\", \"question_type\": \"multiple\"}, {\"answer\": \"A,B,C,D\", \"analysis\": \"起重机安全操作要求包括不超载、不斜吊、吊物下不站人、定期检查钢丝绳。操作中玩手机是违章行为。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 65, \"question_text\": \"起重机安全操作要求包括？\", \"question_type\": \"multiple\"}, {\"answer\": \"B,D,E\", \"analysis\": \"电气火灾应使用干粉灭火器、二氧化碳灭火器或干砂扑救。泡沫和水型灭火器不能用于电气火灾。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 66, \"question_text\": \"车间电气火灾的扑救应使用哪些灭火器？\", \"question_type\": \"multiple\"}, {\"answer\": \"A,B,C,D\", \"analysis\": \"压力容器操作人员应持证上岗、熟悉操作规程、掌握应急处置、了解设备结构。检修资质不是操作人员必备条件。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 67, \"question_text\": \"压力容器操作人员应具备哪些条件？\", \"question_type\": \"multiple\"}, {\"answer\": \"A,B,C,E\", \"analysis\": \"急救箱应配备创可贴、消毒药水、绷带、止血带等急救用品。感冒药不属于急救用品。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 68, \"question_text\": \"车间急救箱应配备哪些物品？\", \"question_type\": \"multiple\"}, {\"answer\": \"A,C,D,E\", \"analysis\": \"叉车作业严禁超载、载人、酒后驾驶、货叉下站人。系安全带是正确安全行为。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 69, \"question_text\": \"叉车作业时严禁哪些行为？\", \"question_type\": \"multiple\"}, {\"answer\": \"A,C,D,E\", \"analysis\": \"车间消防设施包括灭火器、消防栓、消防水带、应急照明等。监控摄像头不属于消防设施。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 70, \"question_text\": \"车间消防设施包括？\", \"question_type\": \"multiple\"}, {\"answer\": \"A,B,C,D\", \"analysis\": \"特种设备定期检验包括外观检查、性能测试、安全附件校验、运行试验等。设备估价不属于检验内容。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 71, \"question_text\": \"特种设备定期检验的内容包括？\", \"question_type\": \"multiple\"}, {\"answer\": \"A,B,C,D,E\", \"analysis\": \"车间安全生产管理制度应包括安全操作规程、安全检查制度、安全教育培训制度、应急救援制度、奖惩制度等。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 72, \"question_text\": \"车间安全生产管理制度应包括？\", \"question_type\": \"multiple\"}, {\"answer\": \"A,B,C,E\", \"analysis\": \"叉车日常维护保养包括清洁车辆、检查液位、润滑各部位、紧固螺栓等。更换轮胎属于维修，不属于日常保养。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 73, \"question_text\": \"叉车日常维护保养内容包括？\", \"question_type\": \"multiple\"}, {\"answer\": \"A,B,C,D\", \"analysis\": \"危险化学品应分类存放、标识清晰、专人管理、配备防护用品。严禁随意混合存放。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 74, \"question_text\": \"车间危险化学品管理要求包括？\", \"question_type\": \"multiple\"}, {\"answer\": \"A,C,E\", \"analysis\": \"电梯困人时应按下紧急呼叫按钮、拨打救援电话、等待专业人员救援。严禁强行扒门逃生或在轿厢内跳跃。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 75, \"question_text\": \"电梯困人时正确的处理方法是？\", \"question_type\": \"multiple\"}, {\"answer\": \"A\", \"analysis\": \"安全通道必须保持畅通，严禁堆放任何物料。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 76, \"question_text\": \"车间安全通道上可以临时堆放物料。\", \"question_type\": \"judge\"}, {\"answer\": \"B\", \"analysis\": \"叉车驾驶员必须取得叉车操作证方可上岗作业。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 77, \"question_text\": \"叉车驾驶员必须持证上岗。\", \"question_type\": \"judge\"}, {\"answer\": \"B\", \"analysis\": \"锅炉水位低于安全水位时必须立即停炉补水，严禁继续运行，防止锅炉爆炸。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 78, \"question_text\": \"锅炉运行中水位低于安全水位时可以继续运行。\", \"question_type\": \"judge\"}, {\"answer\": \"A\", \"analysis\": \"车间内严禁吸烟，防止火灾事故发生。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 79, \"question_text\": \"车间内禁止吸烟。\", \"question_type\": \"judge\"}, {\"answer\": \"B\", \"analysis\": \"压力容器安全阀严禁随意调整，必须由专业人员按规定进行校验和调整。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 80, \"question_text\": \"压力容器安全阀可以随意调整。\", \"question_type\": \"judge\"}, {\"answer\": \"A\", \"analysis\": \"设备检修必须切断电源并悬挂“禁止合闸”警示牌，防止他人误操作。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 81, \"question_text\": \"设备检修时必须切断电源并悬挂警示牌。\", \"question_type\": \"judge\"}, {\"answer\": \"A\", \"analysis\": \"叉车严禁载人行驶，只允许驾驶员一人操作。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 82, \"question_text\": \"叉车可以载人行驶。\", \"question_type\": \"judge\"}, {\"answer\": \"B\", \"analysis\": \"电梯紧急停止按钮按下后，电梯会立即停止运行，防止危险发生。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 83, \"question_text\": \"电梯紧急停止按钮按下后电梯会立即停止运行。\", \"question_type\": \"judge\"}, {\"answer\": \"B\", \"analysis\": \"灭火器使用前必须检查压力表，确认压力在正常范围内才能使用。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 84, \"question_text\": \"灭火器使用前不必检查压力表。\", \"question_type\": \"judge\"}, {\"answer\": \"A\", \"analysis\": \"起重机吊物下严禁人员停留和通过，防止吊物坠落伤人。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 85, \"question_text\": \"起重机吊物下禁止人员停留。\", \"question_type\": \"judge\"}, {\"answer\": \"A\", \"analysis\": \"车间内操作设备必须穿安全鞋，严禁穿凉鞋、拖鞋等易滑鞋具。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 86, \"question_text\": \"车间内可以穿凉鞋操作设备。\", \"question_type\": \"judge\"}, {\"answer\": \"B\", \"analysis\": \"特种设备必须按照规定的周期进行定期检验，确保设备安全运行。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 87, \"question_text\": \"特种设备必须定期检验。\", \"question_type\": \"judge\"}, {\"answer\": \"B\", \"analysis\": \"轮胎气压是叉车日常检查的重要项目，气压不足会影响叉车稳定性。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 88, \"question_text\": \"叉车日常检查中轮胎气压不属于检查项目。\", \"question_type\": \"judge\"}, {\"answer\": \"B\", \"analysis\": \"消防栓前严禁堆放任何物品，确保消防栓随时可用。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 89, \"question_text\": \"车间消防栓前可以堆放少量物品。\", \"question_type\": \"judge\"}, {\"answer\": \"A\", \"analysis\": \"锅炉运行时水位必须保持在正常水位线范围内，缺水或满水都会造成安全事故。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 90, \"question_text\": \"锅炉运行时必须保持水位在正常范围内。\", \"question_type\": \"judge\"}, {\"answer\": \"B\", \"analysis\": \"车间内工作必须佩戴安全帽，保护头部安全。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 91, \"question_text\": \"在车间内工作可以不佩戴安全帽。\", \"question_type\": \"judge\"}, {\"answer\": \"A\", \"analysis\": \"起重机吊钩出现裂纹时必须立即报废更换，严禁继续使用。\", \"selected\": \"\", \"is_correct\": false, \"question_id\": 92, \"question_text\": \"起重机吊钩出现裂纹时应继续使用。\", \"question_type