INSERT INTO `safety_exam_question` VALUES (1,'Q-20260806-0001','single','车间安全生产的第一责任人是？','[{\"text\": \"安全员\", \"label\": \"A\"}, {\"text\": \"车间主任\", \"label\": \"B\"}, {\"text\": \"班组长\", \"label\": \"C\"}, {\"text\": \"操作工\", \"label\": \"D\"}]','B','车间主任是车间安全生产的第一责任人，对车间安全生产工作全面负责。','easy',5,0,1,'2026-08-06 15:01:25','2026-08-06 15:01:25',NULL),(2,'Q-20260806-0002','single','我国安全生产的方针是？','[{\"text\": \"安全第一、预防为主、综合治理\", \"label\": \"A\"}, {\"text\": \"安全第一、防治结合\", \"label\": \"B\"}, {\"text\": \"预防为主、安全第一\", \"label\": \"C\"}, {\"text\": \"安全第一、质量为主\", \"label\": \"D\"}]','A','《安全生产法》规定，安全生产工作应当以人为本，坚持安全第一、预防为主、综合治理的方针。','easy',5,0,1,'2026-08-06 15:01:25','2026-08-06 15:01:25',NULL),(3,'Q-20260806-0003','single','特种作业人员必须取得什么证书方可上岗？','[{\"text\": \"毕业证\", \"label\": \"A\"}, {\"text\": \"特种作业操作证\", \"label\": \"B\"}, {\"text\": \"身份证\", \"label\": \"C\"}, {\"text\": \"健康证\", \"label\": \"D\"}]','B','特种作业人员必须按照国家有关规定经专门的安全作业培训，取得特种作业操作资格证书，方可上岗作业。','easy',3,0,1,'2026-08-06 15:01:25','2026-08-06 15:01:25',NULL),(4,'Q-20260806-0004','single','发现火灾隐患应当如何处理？','[{\"text\": \"置之不理\", \"label\": \"A\"}, {\"text\": \"立即报告并采取相应措施\", \"label\": \"B\"}, {\"text\": \"等有时间再处理\", \"label\": \"C\"}, {\"text\": \"自己悄悄处理\", \"label\": \"D\"}]','B','发现火灾隐患应当立即报告，并采取相应的防范措施，避免火灾事故发生。','easy',5,0,1,'2026-08-06 15:01:25','2026-08-06 15:01:25',NULL),(5,'Q-20260806-0005','single','使用灭火器扑救火灾时，应对准火焰的哪个部位喷射？','[{\"text\": \"火焰顶部\", \"label\": \"A\"}, {\"text\": \"火焰中部\", \"label\": \"B\"}, {\"text\": \"火焰根部\", \"label\": \"C\"}, {\"text\": \"任意部位\", \"label\": \"D\"}]','C','灭火器应对准火焰根部喷射，才能有效扑灭火源。','normal',5,0,1,'2026-08-06 15:01:25','2026-08-06 15:01:25',NULL),(6,'Q-20260806-0006','single','车间内安全通道的宽度一般不应小于？','[{\"text\": \"0.5米\", \"label\": \"A\"}, {\"text\": \"1米\", \"label\": \"B\"}, {\"text\": \"1.5米\", \"label\": \"C\"}, {\"text\": \"2米\", \"label\": \"D\"}]','C','车间安全通道宽度一般不小于1.5米，确保人员疏散和车辆通行安全。','normal',5,0,1,'2026-08-06 15:01:26','2026-08-06 15:01:26',NULL),(7,'Q-20260806-0007','single','下列哪种行为不属于违章操作？','[{\"text\": \"戴手套操作旋转机床\", \"label\": \"A\"}, {\"text\": \"穿高跟鞋进入车间\", \"label\": \"B\"}, {\"text\": \"戴安全帽进入车间\", \"label\": \"C\"}, {\"text\": \"酒后上岗作业\", \"label\": \"D\"}]','C','戴安全帽是正确安全行为，其余三项均为违章操作行为。','easy',5,0,1,'2026-08-06 15:01:26','2026-08-06 15:01:26',NULL),(8,'Q-20260806-0008','single','设备检修时，应在电源开关处悬挂什么标识？','[{\"text\": \"正在运行\", \"label\": \"A\"}, {\"text\": \"禁止合闸\", \"label\": \"B\"}, {\"text\": \"注意安全\", \"label\": \"C\"}, {\"text\": \"严禁烟火\", \"label\": \"D\"}]','B','设备检修时必须在电源开关处悬挂“禁止合闸”标识，防止他人误操作。','normal',5,0,1,'2026-08-06 15:01:26','2026-08-06 15:01:26',NULL),(9,'Q-20260806-0009','single','叉车在厂区道路行驶时，速度一般不得超过？','[{\"text\": \"5km/h\", \"label\": \"A\"}, {\"text\": \"10km/h\", \"label\": \"B\"}, {\"text\": \"15km/h\", \"label\": \"C\"}, {\"text\": \"20km/h\", \"label\": \"D\"}]','B','叉车在厂区道路行驶速度一般不超过10km/h，在车间内不超过5km/h。','normal',7,0,1,'2026-08-06 15:01:26','2026-08-06 15:01:26',NULL),(10,'Q-20260806-0010','single','锅炉运行中，水位表应每班冲洗几次？','[{\"text\": \"1次\", \"label\": \"A\"}, {\"text\": \"2次\", \"label\": \"B\"}, {\"text\": \"至少1次\", \"label\": \"C\"}, {\"text\": \"3次\", \"label\": \"D\"}]','C','锅炉水位表每班至少冲洗一次，确保水位显示清晰准确。','hard',3,0,1,'2026-08-06 15:01:26','2026-08-06 15:01:26',NULL),(11,'Q-20260806-0011','single','车间内噪音超过多少分贝时应佩戴防护耳塞？','[{\"text\": \"60dB\", \"label\": \"A\"}, {\"text\": \"75dB\", \"label\": \"B\"}, {\"text\": \"85dB\", \"label\": \"C\"}, {\"text\": \"100dB\", \"label\": \"D\"}]','C','车间噪音超过85分贝时，操作人员应佩戴防护耳塞，保护听力。','normal',5,0,1,'2026-08-06 15:01:26','2026-08-06 15:01:26',NULL),(12,'Q-20260806-0012','single','化学品泄漏时应首先采取什么措施？','[{\"text\": \"立即清理\", \"label\": \"A\"}, {\"text\": \"切断泄漏源\", \"label\": \"B\"}, {\"text\": \"报告领导\", \"label\": \"C\"}, {\"text\": \"撤离现场\", \"label\": \"D\"}]','B','化学品泄漏时应首先切断泄漏源，防止泄漏扩大，然后再进行清理和报告。','normal',5,0,1,'2026-08-06 15:01:26','2026-08-06 15:01:26',NULL),(13,'Q-20260806-0013','single','叉车装卸货物时，货叉离地高度应保持在？','[{\"text\": \"100-200mm\", \"label\": \"A\"}, {\"text\": \"200-300mm\", \"label\": \"B\"}, {\"text\": \"300-400mm\", \"label\": \"C\"}, {\"text\": \"400-500mm\", \"label\": \"D\"}]','B','叉车装卸货物时货叉离地高度应保持在200-300mm，确保行驶稳定。','hard',7,0,1,'2026-08-06 15:01:26','2026-08-06 15:01:26',NULL),(14,'Q-20260806-0014','single','以下哪种灭火器适用于扑救电器火灾？','[{\"text\": \"泡沫灭火器\", \"label\": \"A\"}, {\"text\": \"干粉灭火器\", \"label\": \"B\"}, {\"text\": \"水型灭火器\", \"label\": \"C\"}, {\"text\": \"酸碱灭火器\", \"label\": \"D\"}]','B','干粉灭火器适用于扑救电器火灾，水型灭火器不能用于电器火灾。','normal',5,0,1,'2026-08-06 15:01:26','2026-08-06 15:01:26',NULL),(15,'Q-20260806-0015','single','车间安全电压为？','[{\"text\": \"220V\", \"label\": \"A\"}, {\"text\": \"380V\", \"label\": \"B\"}, {\"text\": \"36V\", \"label\": \"C\"}, {\"text\": \"12V\", \"label\": \"D\"}]','C','车间内行灯、手持电动工具等应采用36V及以下安全电压。','normal',5,0,1,'2026-08-06 15:01:26','2026-08-06 15:01:26',NULL),(16,'Q-20260806-0016','single','特种设备使用单位应在设备投入使用前多少日内办理使用登记？','[{\"text\": \"15日\", \"label\": \"A\"}, {\"text\": \"30日\", \"label\": \"B\"}, {\"text\": \"45日\", \"label\": \"C\"}, {\"text\": \"60日\", \"label\": \"D\"}]','B','特种设备使用单位应当在设备投入使用前或者投入使用后30日内办理使用登记。','hard',3,0,1,'2026-08-06 15:01:26','2026-08-06 15:01:26',NULL),(17,'Q-20260806-0017','single','起重机吊运重物时，吊钩应垂直起吊，斜吊角度不得超过？','[{\"text\": \"3°\", \"label\": \"A\"}, {\"text\": \"5°\", \"label\": \"B\"}, {\"text\": \"10°\", \"label\": \"C\"}, {\"text\": \"15°\", \"label\": \"D\"}]','B','起重机吊运重物时吊钩应垂直起吊，斜吊角度不得超过5°，防止钢丝绳脱槽。','hard',3,0,1,'2026-08-06 15:01:26','2026-08-06 15:01:26',NULL),(18,'Q-20260806-0018','single','车间内消防栓周围多少米内不得堆放物品？','[{\"text\": \"1米\", \"label\": \"A\"}, {\"text\": \"1.5米\", \"label\": \"B\"}, {\"text\": \"2米\", \"label\": \"C\"}, {\"text\": \"3米\", \"label\": \"D\"}]','B','消防栓周围1.5米内不得堆放物品，确保消防栓能够快速取用。','normal',5,0,1,'2026-08-06 15:01:26','2026-08-06 15:01:26',NULL),(19,'Q-20260806-0019','single','电梯维护保养应至少每多少日进行一次？','[{\"text\": \"7日\", \"label\": \"A\"}, {\"text\": \"15日\", \"label\": \"B\"}, {\"text\": \"30日\", \"label\": \"C\"}, {\"text\": \"60日\", \"label\": \"D\"}]','B','电梯维护保养应至少每15日进行一次，确保电梯安全运行。','hard',3,0,1,'2026-08-06 15:01:26','2026-08-06 15:01:26',NULL),(20,'Q-20260806-0020','single','以下哪项不是车间常见的安全标志颜色？','[{\"text\": \"红色\", \"label\": \"A\"}, {\"text\": \"黄色\", \"label\": \"B\"}, {\"text\": \"蓝色\", \"label\": \"C\"}, {\"text\": \"绿色\", \"label\": \"D\"}]','C','安全标志颜色中红色表示禁止，黄色表示警告，绿色表示指示，蓝色表示指令。','normal',5,0,1,'2026-08-06 15:01:26','2026-08-06 15:01:26',NULL),(21,'Q-20260806-0021','single','压力容器的安全阀应每年校验几次？','[{\"text\": \"1次\", \"label\": \"A\"}, {\"text\": \"2次\", \"label\": \"B\"}, {\"text\": \"3次\", \"label\": \"C\"}, {\"text\": \"4次\", \"label\": \"D\"}]','A','压力容器安全阀每年至少校验一次，确保安全阀灵敏可靠。','hard',3,0,1,'2026-08-06 15:01:26','2026-08-06 15:01:26',NULL),(22,'Q-20260806-0022','single','车间配电箱的门应保持什么状态？','[{\"text\": \"开启\", \"label\": \"A\"}, {\"text\": \"关闭\", \"label\": \"B\"}, {\"text\": \"半开\", \"label\": \"C\"}, {\"text\": \"拆除\", \"label\": \"D\"}]','B','配电箱门应保持关闭状态，防止无关人员接触带电设备。','easy',5,0,1,'2026-08-06 15:01:26','2026-08-06 15:01:26',NULL),(23,'Q-20260806-0023','single','叉车驾驶员必须持有哪类驾驶证？','[{\"text\": \"汽车驾驶证\", \"label\": \"A\"}, {\"text\": \"叉车操作证\", \"label\": \"B\"}, {\"text\": \"起重机操作证\", \"label\": \"C\"}, {\"text\": \"电工证\", \"label\": \"D\"}]','B','叉车驾驶员必须持有叉车操作证，方可上岗操作叉车。','easy',7,0,1,'2026-08-06 15:01:26','2026-08-06 15:01:26',NULL),(24,'Q-20260806-0024','single','以下哪种情况不属于特种设备事故？','[{\"text\": \"锅炉爆炸\", \"label\": \"A\"}, {\"text\": \"电梯困人\", \"label\": \"B\"}, {\"text\": \"叉车撞人\", \"label\": \"C\"}, {\"text\": \"设备正常停机\", \"label\": \"D\"}]','D','设备正常停机不属于事故，其他三项均属于特种设备事故。','normal',3,0,1,'2026-08-06 15:01:26','2026-08-06 15:01:26',NULL),(25,'Q-20260806-0025','single','车间安全出口应保持什么状态？','[{\"text\": \"锁闭\", \"label\": \"A\"}, {\"text\": \"畅通\", \"label\": \"B\"}, {\"text\": \"半开\", \"label\": \"C\"}, {\"text\": \"堆放货物\", \"label\": \"D\"}]','B','车间安全出口应保持畅通，不得锁闭或堆放物品，确保紧急疏散。','easy',5,0,1,'2026-08-06 15:01:26','2026-08-06 15:01:26',NULL),(26,'Q-20260806-0026','single','压力容器操作人员应