INSERT INTO `salary_config_items` VALUES (22,0,'basic_wage','基本工资',1,'basic_wage','formula','{\"type\":\"conditional\",\"condition\":\"work_days >= standard_work_days\",\"then\":\"basic_wage_standard\",\"else\":\"basic_wage_standard * work_days / standard_work_days\"}','[\"basic_wage_standard\", \"work_days\", \"standard_work_days\"]',0.00,1,1,1,1,'2026-08-21 18:29:59','2026-08-21 20:36:00'),(23,0,'position_wage','职务/岗位工资',1,'basic_wage','formula','{\"type\":\"conditional\",\"condition\":\"work_days + overtime_sat + overtime_sun >= standard_work_days\",\"then\":\"position_wage_standard\",\"else\":\"position_wage_standard * (work_days + overtime_sat + overtime_sun) / standard_work_days\"}','[\"position_wage_standard\", \"work_days\", \"overtime_sat\", \"overtime_sun\", \"standard_work_days\"]',0.00,2,1,1,1,'2026-08-21 18:29:59','2026-08-21 20:36:00'),(24,0,'daily_assessment','日常考核工资',1,'basic_wage','formula','{\"type\":\"conditional\",\"condition\":\"work_days < 16\",\"then\":0,\"else_if\":\"work_days >= standard_work_days\",\"then_if\":\"daily_assessment_standard\",\"else\":\"daily_assessment_standard * work_days / standard_work_days\"}','[\"daily_assessment_standard\", \"work_days\", \"standard_work_days\"]',0.00,3,1,1,1,'2026-08-21 18:29:59','2026-08-21 20:36:00'),(25,0,'actual_basic_wage','当月基本工资',1,'basic_wage','formula','{\"type\":\"conditional\",\"condition\":\"work_days >= standard_work_days\",\"then\":\"basic_wage_standard\",\"else\":\"basic_wage_standard - (basic_wage_standard / standard_work_days) * (standard_work_days - work_days)\"}','[\"basic_wage_standard\", \"work_days\", \"standard_work_days\"]',0.00,4,1,1,1,'2026-08-21 18:29:59','2026-08-21 20:36:00'),(26,0,'overtime_pay','双休日/节假日/其它加班工资',1,'allowance','formula','{\"type\":\"formula\",\"expression\":\"(basic_wage_standard / standard_work_days) * (overtime_sat * 2 + overtime_sun * 2 + overtime_holiday * 3 + overtime_other * 1 + leave_days * 1)\"}','[\"basic_wage_standard\", \"standard_work_days\", \"overtime_sat\", \"overtime_sun\", \"overtime_holiday\", \"overtime_other\", \"leave_days\"]',0.00,5,1,1,1,'2026-08-21 18:29:59','2026-08-21 20:36:00'),(27,0,'actual_position_wage','当月职务/岗位工资',1,'basic_wage','formula','{\"type\":\"conditional\",\"condition\":\"work_days + overtime_sat + overtime_sun >= standard_work_days\",\"then\":\"position_wage_standard\",\"else\":\"position_wage_standard - (position_wage_standard / standard_work_days) * (standard_work_days - (work_days + overtime_sat + overtime_sun))\"}','[\"position_wage_standard\", \"work_days\", \"overtime_sat\", \"overtime_sun\", \"standard_work_days\"]',0.00,6,1,1,1,'2026-08-21 18:29:59','2026-08-21 20:36:00'),(28,0,'actual_daily_assessment','当月日常考核',1,'basic_wage','formula','{\"type\":\"conditional\",\"condition\":\"work_days < 16\",\"then\":0,\"else_if\":\"work_days >= standard_work_days\",\"then_if\":\"daily_assessment_standard\",\"else\":\"daily_assessment_standard - (daily_assessment_standard / standard_work_days) * (standard_work_days - work_days)\"}','[\"daily_assessment_standard\", \"work_days\", \"standard_work_days\"]',0.00,7,1,1,1,'2026-08-21 18:29:59','2026-08-21 20:36:00'),(29,0,'seniority_wage','工龄工资',1,'allowance','formula','{\"type\":\"conditional\",\"condition\":\"work_days + overtime_sat + overtime_sun + overtime_holiday + leave_days < 16\",\"then\":0,\"else_if\":\"work_days + overtime_sat + overtime_sun + overtime_holiday + leave_days >= standard_work_days\",\"then_if\":\"seniority_wage_base\",\"else\":\"seniority_wage_base * (work_days + overtime_sat + overtime_sun + overtime_holiday + leave_days) / standard_work_days\"}','[\"seniority_wage_base\", \"work_days\", \"overtime_sat\", \"overtime_sun\", \"overtime_holiday\", \"leave_days\", \"standard_work_days\"]',0.00,8,1,1,1,'2026-08-21 18:29:59','2026-08-21 20:36:00'),(30,0,'education_subsidy','学历补助',1,'allowance','fixed','{\"type\":\"fixed\",\"value\":200}','[]',200.00,9,1,1,1,'2026-08-21 18:29:59','2026-08-21 20:36:00'),(31,0,'title_subs