-- Dumping data for table `settings_company`
--

LOCK TABLES `settings_company` WRITE;
/*!40000 ALTER TABLE `settings_company` DISABLE KEYS */;
INSERT INTO `settings_company` VALUES (1,'山西大运华能装备制造有限公司','大运华能','Shanxi Dayun Huanneng Equipment Manufacturing Co., Ltd.','李军','91140925MA0LHFD45L','3000万人民币（实缴3000万）','2021-03-26','2021-03-26','2099-12-31',1,'limited','专用设备制造业 / 矿山机械制造','矿用机械装备的设计、制造、销售、维修、租赁及技术服务；矿用装备零配件的制造、销售；洗选煤设备、环保设备、物料搬运设备、圆环链条、激光加工设备、仪器仪表、模具及机械零部件制造；机电安装工程；工业自动化装备及配件的制造、销售、维修及技术服务。','18535078148','400-XXX-XXXX','0350-XXXXXXX','18535078148@163.com','https://www.huanneng.com','036700','山西省忻州市宁武县阳方口镇大水口（工业园区）','中国工商银行忻州分行宁武支行','1234567890123456789','basic','1021XXXXXXXXX','李建军','[]','[]','[]','[]','[]','[]','[]','[]','[]','[]','[]','以质量取得信誉、以服务赢得市场','主色 #1A3C6E / 辅色 #409EFF','','','','','',0,'','','晋ICP备XXXXXXXX号','晋公网安备 14000000000000号','Copyright © 2026 山西大运华能装备制造有限公司 版权所有','山西大运华能装备制造有限公司','enterprise','山西大运华能装备制造有限公司是宁武县属煤炭集团主体企业——山西宁武大运华盛能源集团有限公司的全资子公司。公司于2021年3月26日注册成立，2021年启动项目建设，2023年主体工程竣工，2024年完成基础设施建设和前期设备安装，2025年6月13日正式开业投产。累计投入资金超1.8亿元。公司位于山西省忻州市宁武县阳方口镇大水口工业园区，占地102亩，建筑面积6.9万平方米，建成智能化装备基地，配置50余台（套）先进机器设备，构建了涵盖缸体拆解、激光熔覆、数控加工、智能测试等环节的全流程生产线。公司现有员工57人（2025年数据），技术岗位占比超85%。在资质方面，公司已完成\"三体系认证\"，取得13项矿用产品检修资质证书，具备综采液压支架、采煤机、掘进机、刮板输送机、减速机、电机及皮带运输系统等设备的整体维修维护能力。公司已与郑州煤矿机械集团股份有限公司、三一重工股份有限公司、山西平阳重工机械有限责任公司、山东矿机集团股份有限公司等行业领军企业签署战略合作协议。公司目标是打造全省优质煤机装备制造龙头企业，计划3年内实现产值2亿元，利税近0.1亿元。','112.3','39.0','山西省忻州市宁武县阳方口镇大水口工业园区','乘车至宁武县阳方口镇大水口工业园区','published','2026-08-12 11:26:02',3,'2026-08-11 17:03:05','2026-08-12 11:26:02');
/*!40000 ALTER TABLE `settings_company` ENABLE KEYS */;
UNLOCK TABLES;

