INSERT INTO `system_versions` VALUES (1,'admin','PC管理端','v1.0.0','SC Admin 初始版本',1,3,'2026-08-13 15:12:13','系统初始完成版本，包含客户管理、供应商管理、产品管理、订单管理、采购管理、设备管理、安全管理等基础模块。',NULL,NULL,NULL,0,1,0,NULL,0,0,0,NULL,NULL,0,0,2,'2026-08-13 16:25:45','[{\"stage\":1,\"stage_name\":\"前端资源更新\",\"status\":2,\"status_text\":\"成功\",\"detail\":{\"action\":\"skip\",\"message\":\"未配置热更新部署脚本，前端资源更新由运维人工执行（配置项 hot_update_deploy_script）\"},\"error\":\"\"},{\"stage\":2,\"stage_name\":\"后端代码更新\",\"status\":2,\"status_text\":\"成功\",\"detail\":{\"action\":\"skip\",\"message\":\"未配置热更新部署脚本，后端代码更新由运维人工执行（配置项 hot_update_deploy_script）\"},\"error\":\"\"},{\"stage\":3,\"stage_name\":\"数据库迁移\",\"status\":2,\"status_text\":\"成功\",\"detail\":{\"action\":\"skip\",\"message\":\"项目采用手工 SQL 迁移（database\\/migrations），请人工执行新增迁移文件\"},\"error\":\"\"},{\"stage\":4,\"stage_name\":\"OpCache清除\",\"status\":2,\"status_text\":\"成功\",\"detail\":{\"action\":\"opcache_reset\",\"result\":\"ok\"},\"error\":\"\"},{\"stage\":5,\"stage_name\":\"通知发送\",\"status\":2,\"status_text\":\"成功\",\"detail\":{\"action\":\"notify\",\"message\":\"站内信通知已发送（版本 v1.0.0）\"},\"error\":\"\"}]',0,'system','2026-08-13 15:12:13','2026-08-13 16:49:20',NULL),(2,'admin','PC管理端','v1.1.0','新增配件领用功能',1,3,'2026-08-13 15:13:12','新增配件领用（车间领料）功能，支持生产领料、维修领料、研发领料等场景，包含完整的审核流程、库存扣减和成本核算功能。',NULL,NULL,NULL,3,1,0,NULL,0,0,0,NULL,NULL,1,0,2,'2026-08-13 15:13:21','[{\"stage\":1,\"stage_name\":\"前端资源更新\",\"status\":2,\"status_text\":\"成功\",\"detail\":{\"action\":\"skip\",\"message\":\"未配置热更新部署脚本，前端资源更新由运维人工执行（配置项 hot_update_deploy_script）\"},\"error\":\"\"},{\"stage\":2,\"stage_name\":\"后端代码更新\",\"status\":2,\"status_text\":\"成功\",\"detail\":{\"action\":\"skip\",\"message\":\"未配置热更新部署脚本，后端代码更新由运维人工执行（配置项 hot_update_deploy_script）\"},\"error\":\"\"},{\"stage\":3,\"stage_name\":\"数据库迁移\",\"status\":2,\"status_text\":\"成功\",\"detail\":{\"action\":\"skip\",\"message\":\"项目采用手工 SQL 迁移（database\\/migrations），请人工执行新增迁移文件\"},\"error\":\"\"},{\"stage\":4,\"stage_name\":\"OpCache清除\",\"status\":2,\"status_text\":\"成功\",\"detail\":{\"action\":\"opcache_reset\",\"result\":\"ok\"},\"error\":\"\"},{\"stage\":5,\"stage_name\":\"通知发送\",\"status\":2,\"status_text\":\"成功\",\"detail\":{\"action\":\"notify\",\"message\":\"站内信通知已发送（版本 v1.1.0）\"},\"error\":\"\"}]',0,'system','2026-08-13 15:12:13','2026-08-13 15:13:21',NULL),(3,'admin','PC管理端','v1.1.1','页面布局与部署优化',1,3,'2026-08-13 16:19:21','本次更新聚焦页面布局与部署体验优化：\n1. 页脚新增「历史版本」链接，可跳转更新日志公开页；\n2. 修复页脚不在页面最底部、遮挡后台内容的问题；\n3. 前端部署改为原子切换方式，构建期间不再出现 403；\n4. 更新日志公开页支持「返回系统」登录态判断与版本详情跳转；\n5. 版本详情页增加「版本不存在」空态与加载失败重试。',NULL,NULL,NULL,0,1,0,NULL,0,0,0,NULL,NULL,0,0,2,NULL,NULL,0,'system','2026-08-13 16:19:21','2026-08-13 16:19:21',NULL),(4,'admin','PC管理端','v1.1.2','检查更新交互修复',1,3,'2026-08-13 16:19:21','本次更新修复「检查更新」交互问题：\n1. 修复点击「检查更新」后全屏遮罩未关闭导致灰页面、立即更新无法点击的问题；\n2. 检查更新请求增加 10 秒超时保护，网络异常时快速提示，不再无限等待。',NULL,NULL,NULL,0,1,0,NULL,0,0,0,NULL,NULL,0,0,2,NULL,NULL,0,'system','2026-08-13 16:19:21','2026-08-13 16:49:20',NULL),(5,'admin','PC管理端','v1.2.0','新增配件退库功能',1,3,'2026-08-13 16:49:20','本次更新新增配件退库（退库管理）功能：\n1. 支持生产退库、维修退库、质量退库等场景；\n2. 关联领料单形成从领料到退库的完整闭环；\n3. 包含审核流程（提交/通过/驳回/撤销）；\n4. 确认退库自动增加库存并生成库存流水（含成本核算）；\n5. 完整的操作日志审计追溯。',NULL,NULL,NULL,0,1,0,NULL,0,0,0,NULL,NULL,0,0,2,NULL,NULL,0,'system','2026-08-13 16:49:20','2026-08-13 17:14:15',NULL),(6,'admin','PC管理端','v1.3.0','新增报废出库功能',1,3,'2026-08-13 17:14:15','本次更新新增报废出库功能：\n1. 支持质量报废、过期报废、技术淘汰、事故损坏等场景；\n2. 包含审核流程（提交/通过/驳回/撤销）；\n3. 确认报废自动扣减库存并生成库存流水（含成本核销）；\n4. 可关联领料单追溯报废物料来源；\n5. 完整的操作日志审计追溯。',NULL,NULL,NULL,0,1,0,NULL,0,0,0,NULL,NULL,0,0,2,NULL,NULL,0,'system','2026-08-13 17:14:15','2026-08-13 17:19:56',NULL),(7,'admin','PC管理端','v1.3.1','报废出库功能修复',1,3,'2026-08-13 17:18:52','本次更新为修复批次（v1.3.1）：\n1. 修复报废单部门名称未保存的问题；\n2. 报废单/退库单详情页审核人由 ID 改为显示姓名。',NULL,NULL,NULL,0,1,0,NULL,0,0,0,NULL,NULL,0,0,2,NULL,NULL,0,'system','2026-08-13 17:18:52','2026-08-13 17:24:43',NULL),(8,'admin','PC管理端','v1.3.2','检查更新体验优化',1,3,'2026-08-13 17:24:43','本次更新为检查更新体验优化：\n1. 「稍后提醒」2 小时后页面内自动再次检测弹窗（无需刷新页面）；\n2. 无新版本提示改为 1.5 秒轻提示自动消失。',NULL,NULL,NULL,0,1,0,NULL,0,0,0,NULL,NULL,0,0,2,NULL,NULL,0,'system','2026-08-13 17:24:43','2026-08-13 17:57:44',NULL),(9,'admin','PC管理端','v1.4.2','新增产品接收功能',1,3,'2026-08-13 17:57:44','本次更新新增产品接收（设备入库）功能：\n1. 支持维修完成入库、调拨入库、盘盈入库、其他入库等场景；\n2. 关联经营管理产品接收管理（/business/receive），维修完成设备正式入库；\n3. 包含审核流程（提交/通过/驳回/撤销）；\n4. 确认入库自动增加库存并生成库存流水（含成本核算）；\n5. 自动回写产品接收单入库状态，形成拉回→维修→入库完整闭环；\n6. 完整的操作日志审计追溯。',NULL,NULL,NULL,0,1,0,NULL,0,0,0,NULL,NULL,0,0,2,NULL,NULL,0,'system','2026-08-13 17:57:44','2026-08-13 18:04:34',NULL),(10,'admin','PC管理端','v1.4.3','库存统计修复',1,3,'2026-08-13 18:04:34','本次更新为 Bug 修复批次（v1.4.3）：\n1. 修复产品入库流水（flow_type=7）混入配件物料库存统计的问题——领料/退库/报废/采购入库/物料列表等库存与成本查询统一排除产品入库流水，避免产品与物料 ID 撞号导致库存数据错误。',NULL,NULL,NULL,0,1,0,NULL,0,0,0,NULL,NULL,0,0,2,NULL,NULL,0,'system','2026-08-13 18:04:34','2026-08-13 18:08:10',NULL),(11,'admin','PC管理端','v1.4.4','更新通知弹窗修复',1,3,'2026-08-13 18:08:10','本次更新为 Bug 修复批次（v1.4.4）：\n1. 修复「系统更新通知」弹窗右上角关闭按钮无响应；\n2. 修复「发现新版本」弹窗右上角关闭按钮无响应（补充 update:visible 绑定）。',NULL,NULL,NULL,0,1,0,NULL,0,0,0,NULL,NULL,0,0,2,NULL,NULL,0,'system','2026-08-13 18:08:10','2026-08-13 18:43:58',NULL),(12,'admin','PC管理端','v1.5.0','新增产品入库功能',1,3,'2026-08-13 18:43:58','本次更新新增产品入库（库存入口）功能：\n1. 来源为产品接收管理（/business/receive），维修完成的产品正式入库上架；\n2. 确认入库写库存流水（flow_type=7 产品入库，material_id 存产品 ID），增加可用库存；\n3. 包含审核流程（提交/通过/驳回/撤销）；\n4. 确认入库完成货位分配与上架确认，自动回写产品接收单入库状态；\n5. 完整的操作日志审计追溯。',NULL,NULL,NULL,0,1,0,NULL,0,0,0,NULL,NULL,0,0,2,NULL,NULL,0,'system','2026-08-13 18:43:58','2026-08-13 19:43:13',NULL),(13,'admin','PC管理端','v1.6.0','新增产品出库功能',1,3,'2026-08-13 19:43:13','新增产品出库功能，支持维修完成交付、调拨出库等场景，包含完整的审核流程和库存扣减功能。',NULL,NULL,NULL,0,1,0,NULL,0,0,0,NULL,NULL,12,0,2,NULL,NULL,0,'system','2026-08-13 19:43:13','2026-08-13 22:25:52',NULL),(14,'admin','PC管理端','v1.6.3','移除右上角检查更新按钮并恢复下拉入口',1,3,'2026-08-13 22:25:52','修复登录页「未提供认证令牌」提示及登录后版本检测未启动问题；移除右上角「检查更新」按钮（用户下拉菜单入口与自动检测保留）。',NULL,NULL,NULL,0,1,0,NULL,0,0,0,NULL,NULL,13,0,2,NULL,NULL,0,'system','2026-08-13 22:25:52','2026-08-14 08:14:28',NULL),(15,'admin','PC管理端','v1.7.0','新增库存查询功能',1,3,'2026-08-14 08:14:28','新增库存查询功能，提供实时库存查询、库存状态标识、库存分析图表、库存预警快捷入口、多维度搜索筛选与行内钻取。',NULL,NULL,NULL,0,1,0,NULL,0,0,0,NULL,NULL,14,0,2,NULL,NULL,0,'system','2026-08-14 08:14:28','2026-08-14 08:22:42',NULL),(16,'admin','PC管理端','v1.7.1','采购申请支持物料搜索',1,3,'2026-08-14 08:22:42','新增采购申请「搜索产品」支持物料管理中的物料（产品与物料合并搜索，物料自动带出参考采购单价）；物料列表接口新增关键字搜索。',NULL,NULL,NULL,0,1,0,NULL,0,0,0,NULL,NULL,15,0,2,NULL,NULL,0,'system','2026-08-14 08:22:42','2026-08-14 08:27:13',NULL),(17,'admin','PC管理端','v1.7.2','采购申请产品搜索优化',1,3,'2026-08-14 08:27:13','采购申请「选择产品」弹窗打开即默认加载全部产品与物料（无需先输入关键字），输入编码/名称可精确搜索。',NULL,NULL,NULL,0,1,0,NULL,0,0,0,NULL,NULL,16,0,2,NULL,NULL,0,'system','2026-08-14 08:27:13','2026-08-14 08:31:30',NULL),(18,'admin','PC管理端','v1.7.3','采购申请部门支持子部门选择',1,3,'2026-08-14 08:31:30','采购申请「申请部门」改为树形级联选择，支持选择任意层级部门（含子部门），编辑回显正确。',NULL,NULL,NULL,0,1,0,NULL,0,0,0,NULL,NULL,17,0,2,NULL,NULL,0,'system','2026-08-14 08:31:30','2026-08-14 08:39:17',NULL),(19,'admin','PC管理端','v1.7.4','产品列表同步到物料管理',1,3,'2026-08-14 08:39:17','物料管理新增「同步产品」：将产品列表中的启用产品一键同步为物料（按编码更新、软删自动恢复），使产品可在采购申请搜索、物料管理与库存查询中使用。',NULL,NULL,NULL,0,1,0,NULL,0,0,0,NULL,NULL,18,0,2,NULL,NULL,0,'system','2026-08-14 08:39:17','2026-08-14 08:47:59',NULL),(20,'admin','PC管理端','v1.7.5','物料编码规则变更同步重建',1,3,'2026-08-14 08:47:59','物料管理新增「重建编码」：修改编码规则后一键按新规则重新生成现有物料编码（自动避免重复，产品同步物料跳过，库存流水按 ID 关联不受影响）。',NULL,NULL,NULL,0,1,0,NULL,0,0,0,NULL,NULL,19,0,2,NULL,NULL,0,'system','2026-08-14 08:47:59','2026-08-14 08:50:38',NULL),(21,'admin','PC管理端','v1.7.6','产品编码同步控制物料编码',1,3,'2026-08-14 08:50:38','产品同步到物料增强：物料按 product_id 与产品关联，产品编码变更后再次同步即自动更新物料编码（冲突时保留原编码），保证产品与物料编码一致。',NULL,NULL,NULL,0,1,0,NULL,0,0,0,NULL,NULL,20,0,2,NULL,NULL,0,'system','2026-08-14 08:50:38','2026-08-14 08:55:44',NULL),(22,'admin','PC管理端','v1.7.7','编码规则同步控制产品编码',1,3,'2026-08-14 08:55:44','「重建编码」扩展为同时重建物料与产品编码：编码规则修改后一键按新规则重生产品与物料编码，产品同步物料编码随产品自动更新（自动避免重复）。',NULL,NULL,NULL,0,1,0,NULL,0,0,0,NULL,NULL,21,0,2,NULL,NULL,0,'system','2026-08-14 08:55:44','2026-08-14 09:01:54',NULL),(23,'admin','PC管理端','v1.7.8','编码规则保存后一键重建编码',1,3,'2026-08-14 09:01:54','编码规则页保存规则后弹窗询问是否立即重建现有物料与产品编码，确认后产品列表与物料编码即按新规则同步更新。',NULL,NULL,NULL,0,1,0,NULL,0,0,0,NULL,NULL,22,0,2,NULL,NULL,0,'system','2026-08-14 09:01:54','2026-08-14 09:13:29',NULL),(24,'admin','PC管理端','v1.7.10','编码规则支持按物料类型首字母前缀',1,3,'2026-08-14 09:13:29','编码规则新增「按物料类型首字母作为前缀」：原材料Y/半成品B/成品C/备件J/辅料F；新增/导入/重建编码均按类型前缀生成，并修复重建编码产品与物料编码冲突导致产品未更新问题。',NULL,NULL,NULL,0,1,0,NULL,0,0,0,NULL,NULL,23,0,2,NULL,NULL,0,'system','2026-08-14 09:13:29','2026-08-14 09:18:32',NULL),(25,'admin','PC管理端','v1.7.11','修复编码规则类型前缀未保存',1,3,'2026-08-14 09:18:32','修复编码规则保存时未保存「按物料类型首字母前缀」开关导致规则不生效的问题：保存规则现完整落库 type_prefix，重建/新增编码按类型前缀生效。',NULL,NULL,NULL,0,1,0,NULL,0,0,0,NULL,NULL,24,0,2,NULL,NULL,0,'system','2026-08-14 09:18:32','2026-08-14 09:23:17',NULL),(26,'admin','PC管理端','v1.7.12','修复重建编码产品编码每次递增',1,3,'2026-08-14 09:23:17','修复「重建编码」产品编码每次重建序号递增的问题：改为幂等重建，旧编码已符合规则时保持不变，仅不符合/冲突的重新分配。',NULL,NULL,NULL,0,1,0,NULL,0,0,0,NULL,NULL,25,0,2,NULL,NULL,0,'system','2026-08-14 09:23:17','2026-08-14 09:34:45',NULL),(27,'admin','PC管理端','v1.8.0','新增库存流水功能',1,3,'2026-08-14 09:34:45','新增库存流水功能：集中展示所有库存变动记录，支持物料/变动类型/来源单据/仓库/日期多维度筛选，来源单据可点击追溯详情，流水详情抽屉查看完整字段，支持导出，并与库存查询联动钻取。',NULL,NULL,NULL,0,1,0,NULL,0,0,0,NULL,NULL,26,0,2,NULL,NULL,0,'system','2026-08-14 09:34:45','2026-08-14 09:50:35',NULL),(28,'admin','PC管理端','v1.9.0','新增库存预警功能',1,3,'2026-08-14 09:50:35','新增库存预警功能：自动识别短缺/偏低/超储库存，预警等级分级，快捷生成采购申请、调整安全库存、忽略预警，支持预警规则配置（启用/阈值/频率）与导出，与库存查询、采购申请形成闭环。',NULL,NULL,NULL,0,1,0,NULL,0,0,0,NULL,NULL,27,0,2,NULL,NULL,0,'system','2026-08-14 09:50:35','2026-08-14 10:06:41',NULL),(29,'admin','PC管理端','v1.9.1','修复仓储配件出入库功能',1,3,'2026-08-14 10:06:41','修复配件领用确认发料与报废新增功能故障：库存流水表补充物料编码/名称冗余列，报废单读取规格字段修正。',NULL,NULL,NULL,0,1,0,NULL,0,0,0,NULL,NULL,28,0,2,NULL,NULL,0,'system','2026-08-14 10:06:41','2026-08-14 10:35:36',NULL),(30,'admin','PC管理端','v1.10.0','新增假勤申请功能',1,3,'2026-08-14 10:35:36','新增假勤申请功能：员工在线发起请假/调休/加班/出差申请，完